      <pre class="p-4 text-sm font-mono text-cyan-300 overflow-x-auto leading-relaxed"><code>trait JsonEncoder[A]:
  def encode(a: A): String

given JsonEncoder[String] with
  def encode(a: String): String = s&quot;\\&quot;\${a}\\&quot;&quot;

extension [A](a: A)(using encoder: JsonEncoder[A])
  def toJson: String = encoder.encode(a)

val payload = &quot;dataradix-stream&quot;.toJson</code></pre>
