      <pre class="p-4 text-sm font-mono text-cyan-300 overflow-x-auto leading-relaxed"><code>import pytest
from chispa.dataframe_comparer import assert_df_equality

def test_filter_active_users(spark):
    source_df = spark.createDataFrame([(&quot;u1&quot;, True), (&quot;u2&quot;, False)], [&quot;id&quot;, &quot;is_active&quot;])
    expected_df = spark.createDataFrame([(&quot;u1&quot;, True)], [&quot;id&quot;, &quot;is_active&quot;])
    actual_df = filter_active(source_df)
    assert_df_equality(actual_df, expected_df)</code></pre>
